-- 商品规格与规格值管理；不新增业务表，不修改角色授权。
BEGIN;
SET @mall_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='mall' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @spec_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@mall_root AND path='specs' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @spec_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@mall_root AND path='spec-values' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
